llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "In patients with liver cirrhosis, verapamil, the closest structural analogue, had an oral bioavailability of 52 ± 13%, directly supporting F ≥ 20% under the query's cirrhosis condition.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "Verapamil absolute bioavailability is 34% in humans under normal conditions, showing that the dimethoxyphenethylamine scaffold can achieve F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "Gallopamil, a close verapamil analogue with additional methoxy substitution, showed 96.3% oral bioavailability in humans, supporting high bioavailability for this structural family.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C17"],
      "claim": "Norverapamil, the desmethyl verapamil analogue, had 34 ± 12% bioavailability in healthy men, supporting high F for close analogues of the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C09"],
      "claim": "Vernakalant, another dimethoxyphenethylamine, had 71 ± 21% absolute oral bioavailability in healthy volunteers, supporting high F for this chemotype.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Bevantolol, a dimethoxyphenethyl amino alcohol, had mean oral bioavailability of 57% (range 26–98%), supporting high F for related dimethoxyphenyl amines.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C41"],
      "claim": "Verapamil bioavailability was 10.5% in healthy volunteers, demonstrating that extensive first-pass metabolism can lower F below 20% in normal conditions; however, the query is assessed under cirrhosis, where verapamil F increases to about 52%.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted high: the query is a verapamil/gallopamil-type dimethoxyphenethylamine. Verapamil F rises to ~52% in cirrhosis, and gallopamil, norverapamil, vernakalant, and bevantolol all show F ≥ 34–96%. Low-F records are mostly from normal-condition verapamil first-pass metabolism or structurally distant terameprocol, and are outweighed by cirrhosis-specific and analogue evidence.",
  "evidence_gaps": [
    "No direct bioavailability measurement exists for the query or a close cyclic-disulfone analogue.",
    "The effect of the cyclic disulfone moiety on intestinal permeability and first-pass metabolism is unknown.",
    "Cirrhosis-specific bioavailability data are available for verapamil but not for the exact query scaffold."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

